package lr2touch;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.MessageDigest;import java.util.concurrent.*;import java.util.function.*;
/** Small overlay and optional LAN control web server; bounded workers and request sizes. */
final class BattleHttp implements AutoCloseable {
 final java.util.Set<Socket> sockets=ConcurrentHashMap.newKeySet();final ServerSocket listener;final ThreadPoolExecutor workers=new ThreadPoolExecutor(2,2,0,TimeUnit.SECONDS,new ArrayBlockingQueue<>(16));volatile boolean closed;final Path root;final Supplier<String> state;final Function<String,Boolean> command;final String adminPassword;
 BattleHttp(int port,Path root,Supplier<String> state,Function<String,Boolean> command,String adminPassword,boolean lan)throws IOException{this.root=root;this.state=state;this.command=command;this.adminPassword=adminPassword;listener=new ServerSocket();listener.bind(new InetSocketAddress(lan?null:InetAddress.getByName("127.0.0.1"),port));BattleWire.thread("battle-overlay",()->{while(!closed)try{Socket socket=listener.accept();sockets.add(socket);try{workers.execute(()->{try{serve(socket);}finally{sockets.remove(socket);}});}catch(RejectedExecutionException e){sockets.remove(socket);socket.close();}}catch(IOException e){}});}
 int port(){return listener.getLocalPort();}
 static String line(InputStream in)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();int c;while((c=in.read())!=-1&&c!='\n'){if(b.size()>=2048)throw new IOException("Header too large");if(c!='\r')b.write(c);}if(c==-1&&b.size()==0)throw new EOFException();return b.toString(StandardCharsets.US_ASCII);}
 void serve(Socket socket){try(socket){socket.setSoTimeout(2000);InputStream in=socket.getInputStream();String[] first=line(in).split(" ");int bytes=0,contentLength=0;for(int i=0;;i++){String h=line(in);bytes+=h.length();if(i>32||bytes>8192)throw new IOException("Too many headers");if(h.isEmpty())break;int colon=h.indexOf(':');if(colon>0&&h.substring(0,colon).equalsIgnoreCase("Content-Length"))contentLength=Integer.parseInt(h.substring(colon+1).trim());}if(first.length!=3){respond(socket,400,"text/plain",new byte[0]);return;}String path=first[1].split("\\?",2)[0];if(first[0].equals("POST")&&path.equals("/command")){if(contentLength<1||contentLength>1024){respond(socket,413,"application/json","{\"ok\":false}".getBytes(StandardCharsets.UTF_8));return;}byte[] body=in.readNBytes(contentLength);String form=new String(body,StandardCharsets.UTF_8);String supplied="",user="",action="";for(String part:form.split("&")){String[] kv=part.split("=",2);if(kv.length==2){String k=URLDecoder.decode(kv[0],"UTF-8"),v=URLDecoder.decode(kv[1],"UTF-8");if(k.equals("password"))supplied=v;if(k.equals("user"))user=v;if(k.equals("action"))action=v;}}boolean ok=user.equals("admin")&&MessageDigest.isEqual(adminPassword.getBytes(StandardCharsets.UTF_8),supplied.getBytes(StandardCharsets.UTF_8))&&command.apply(action);respond(socket,ok?200:403,"application/json",("{\"ok\":"+ok+",\"state\":"+state.get()+"}").getBytes(StandardCharsets.UTF_8));return;}if(!first[0].equals("GET")){respond(socket,405,"text/plain",new byte[0]);return;}if(path.equals("/state.json"))respond(socket,200,"application/json",state.get().getBytes(StandardCharsets.UTF_8));else if(path.equals("/")||path.equals("/index.html")||path.equals("/control.html")||path.equals("/style.css")||path.matches("/(title|artist|player1-name|player1-score|player2-name|player2-score|score-difference)\\.html")){Path file=root.resolve(path.equals("/")?"index.html":path.substring(1));if(Files.size(file)>1048576)throw new IOException("Overlay file too large");respond(socket,200,path.endsWith(".css")?"text/css":"text/html",Files.readAllBytes(file));}else respond(socket,404,"text/plain",new byte[0]);}catch(Exception e){try{socket.close();}catch(Exception ignored){}}}
 static void respond(Socket socket,int status,String type,byte[] data)throws IOException{OutputStream out=socket.getOutputStream();out.write(("HTTP/1.1 "+status+" "+(status==200?"OK":"Error")+"\r\nContent-Type: "+type+"; charset=utf-8\r\nContent-Length: "+data.length+"\r\nCache-Control: no-store\r\nConnection: close\r\nX-Content-Type-Options: nosniff\r\n\r\n").getBytes(StandardCharsets.US_ASCII));out.write(data);out.flush();}
 public void close(){closed=true;try{listener.close();}catch(IOException e){}workers.shutdownNow();for(Socket socket:sockets)try{socket.close();}catch(IOException e){}sockets.clear();}
}
